    {
      "id": "write",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"write\""
        ]
      },
      "label": "Writing a hidden piece"
    },
    {
      "id": "name",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"name\""
        ]
      },
      "label": "Naming a flushed piece"
    },
    {
      "id": "discard",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"discard\""
        ]
      },
      "label": "Discarding an unfinished piece"
