      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"publish\""
        ]
      },
      "label": "Gap details saved before naming the joined file"
    },
    {
      "id": "joinFailed",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"joinFailed\""
        ]
      },
      "label": "Join failed; pieces kept"
    },
    {
      "id": "ready",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"ready\""
        ]
      },
      "label": "Joined file ready; gaps known"
    },
    {
      "id": "deliver",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"deliver\""
        ]
      },
      "label": "Handing over the joined file"
    },
    {
      "id": "deliveryFailed",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"deliveryFailed\""
        ]
      },
      "label": "Hand-over failed; pieces kept"
    },
    {
      "id": "handed",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"handed\""
        ]
      },
      "label": "Handed over; retaining the pieces"
    },
    {
      "id": "remove",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"remove\""
        ]
      },
      "label": "Removing pieces after the retention period"
    },
    {
      "id": "done",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"done\""
        ]
