      "id": "empty",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"empty\""
        ]
      },
      "label": "Nothing was recorded"
    },
    {
      "id": "fallback",
      "when": true,
      "label": "Recording bookkeeping"
    }
  ],
  "step": [
    {
      "id": "crash",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "live"
              },
              "TRUE"
            ]
          },
          {
            "eq": [
              {
                "to": "live"
              },
              "FALSE"
            ]
          }
        ]
      },
      "label": "Crash, kill or power loss"
    },
    {
      "id": "launch",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "live"
              },
              "FALSE"
            ]
          },
          {
            "eq": [
              {
                "to": "live"
              },
              "TRUE"
            ]
          }
        ]
      },
      "label": "Recover from the saved record and disk"
    },
    {
      "id": "write",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"write\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"write\""
            ]
          }
        ]
      },
      "label": "Save a request for the next piece"
    },
    {
      "id": "name",
      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"name\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"name\""
            ]
          }
        ]
      },
      "label": "Save a request to name the flushed piece"
    },
