      "when": {
        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"discard\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"discard\""
            ]
          }
        ]
      },
