        "all": [
          {
            "not": {
              "eq": [
                {
                  "from": "phase"
                },
                "\"joinFailed\""
              ]
            }
          },
          {
            "eq": [
              {
                "to": "phase"
              },
              "\"joinFailed\""
            ]
          }
        ]
      },
      "label": "Report the join error and spool location"
    },
    {
